'use strict';

// MODULES //

var tape = require( 'tape' );
var isEqualDataType = require( '@stdlib/ndarray/base/assert/is-equal-data-type' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var ndarray2array = require( '@stdlib/ndarray/to-array' );
var getDType = require( '@stdlib/ndarray/dtype' );
var ENUMS = require( './../lib/type_enums.js' );
var normalizeArguments = require( './../lib/normalize_arguments.js' );


// VARIABLES //

var TYPES = [ ENUMS.NUMBER, ENUMS.NUMBER, ENUMS.NUMBER, ENUMS.BOOLEAN ];


// FUNCTIONS //

/**
* Returns normalized arguments for a provided base and output data type.
*
* @private
* @param {(number|ndarray)} base - base
* @param {string} bdt - base data type
* @param {string} odt - output data type
* @returns {Array<ndarray>} normalized arguments
*/
function normalize( base, bdt, odt ) {
	var types = TYPES.slice();
	if ( typeof base !== 'number' ) {
		types[ 0 ] = ENUMS.NDARRAY;
	}
	return normalizeArguments( [ base, 0.0, 2.0, true ], types, [ bdt, 'float64', 'float64', 'bool', odt ], [ 2 ], 'row-major' ); // eslint-disable-line max-len
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof normalizeArguments, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a base having the real-valued data type matching the output data type (number)', function test( t ) {
	var expected;
	var values;
	var out;
	var i;

	values = [ 'float32', 'complex64', 'float64', 'complex128' ];
	expected = [ 'float32', 'float32', 'float64', 'float64' ];
	for ( i = 0; i < values.length; i++ ) {
		out = normalize( 10.0, 'float64', values[ i ] );
		t.strictEqual( isEqualDataType( getDType( out[ 0 ] ), expected[ i ] ), true, 'returns expected value when output data type is ' + values[ i ] );
		t.deepEqual( ndarray2array( out[ 0 ] ), [ 10.0, 10.0 ], 'returns expected value when output data type is ' + values[ i ] );
	}
	t.end();
});

tape( 'the function returns a base having the real-valued data type matching the output data type (ndarray)', function test( t ) {
	var expected;
	var values;
	var base;
	var out;
	var i;

	values = [
		[ 'float64', 'float32' ],
		[ 'float64', 'complex64' ],
		[ 'float32', 'float64' ],
		[ 'float32', 'complex128' ],
		[ 'int8', 'float32' ],
		[ 'int32', 'float64' ]
	];
	expected = [ 'float32', 'float32', 'float64', 'float64', 'float32', 'float64' ];
	for ( i = 0; i < values.length; i++ ) {
		base = scalar2ndarray( 10.0, {
			'dtype': values[ i ][ 0 ]
		});
		out = normalize( base, values[ i ][ 0 ], values[ i ][ 1 ] );
		t.strictEqual( isEqualDataType( getDType( out[ 0 ] ), expected[ i ] ), true, 'returns expected value when base data type is ' + values[ i ][ 0 ] + ' and output data type is ' + values[ i ][ 1 ] );
		t.deepEqual( ndarray2array( out[ 0 ] ), [ 10.0, 10.0 ], 'returns expected value when base data type is ' + values[ i ][ 0 ] + ' and output data type is ' + values[ i ][ 1 ] );
	}
	t.end();
});

tape( 'the function throws an error if provided a base ndarray which cannot be safely cast to the real-valued data type matching the output data type', function test( t ) {
	var values;
	var i;

	values = [
		[ 'int32', 'float32' ],
		[ 'uint32', 'complex64' ],
		[ 'generic', 'float64' ]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when base data type is ' + values[ i ][ 0 ] + ' and output data type is ' + values[ i ][ 1 ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var base = scalar2ndarray( 10.0, {
				'dtype': value[ 0 ]
			});
			normalize( base, value[ 0 ], value[ 1 ] );
		};
	}
});
